CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE TABLE public.knowledge_sources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key text NOT NULL UNIQUE,title text NOT NULL,audience text NOT NULL CHECK(audience IN ('all','montor','seller')),enabled boolean NOT NULL DEFAULT true,origin text,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.knowledge_sources TO authenticated;
GRANT ALL ON public.knowledge_sources TO service_role;
ALTER TABLE public.knowledge_sources ENABLE ROW LEVEL SECURITY;
CREATE POLICY knowledge_sources_read ON public.knowledge_sources FOR SELECT TO authenticated USING(true);
CREATE POLICY knowledge_sources_admin ON public.knowledge_sources FOR ALL TO authenticated USING(public.auth_is_admin()) WITH CHECK(public.auth_is_admin());
CREATE TABLE public.knowledge_chunks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_id uuid NOT NULL REFERENCES public.knowledge_sources(id) ON DELETE CASCADE,section text,page int,position int NOT NULL DEFAULT 0,content text NOT NULL,tsv tsvector GENERATED ALWAYS AS (to_tsvector('swedish',coalesce(section,'') || ' ' || content)) STORED,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.knowledge_chunks TO authenticated;
GRANT ALL ON public.knowledge_chunks TO service_role;
ALTER TABLE public.knowledge_chunks ENABLE ROW LEVEL SECURITY;
CREATE POLICY knowledge_chunks_read ON public.knowledge_chunks FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.knowledge_sources s WHERE s.id=source_id AND s.enabled AND (s.audience='all' OR s.audience=public.auth_user_role() OR public.auth_is_admin() OR public.auth_user_role()='coordinator')));
CREATE POLICY knowledge_chunks_admin_write ON public.knowledge_chunks FOR INSERT TO authenticated WITH CHECK(public.auth_is_admin());
CREATE POLICY knowledge_chunks_admin_update ON public.knowledge_chunks FOR UPDATE TO authenticated USING(public.auth_is_admin()) WITH CHECK(public.auth_is_admin());
CREATE POLICY knowledge_chunks_admin_delete ON public.knowledge_chunks FOR DELETE TO authenticated USING(public.auth_is_admin());
CREATE INDEX knowledge_chunks_tsv ON public.knowledge_chunks USING gin(tsv);
CREATE INDEX knowledge_chunks_trigram ON public.knowledge_chunks USING gin(content gin_trgm_ops);
CREATE INDEX knowledge_chunks_source_position ON public.knowledge_chunks(source_id,position);
CREATE FUNCTION public.search_knowledge(p_query text,p_source_key text DEFAULT null,p_limit int DEFAULT 8) RETURNS TABLE(chunk_id uuid,source_key text,source_title text,section text,page int,content text,rank real) LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public AS $$ DECLARE q tsquery; n int; BEGIN IF p_query IS NULL OR length(trim(p_query))=0 THEN RETURN; END IF; IF length(p_query)>500 THEN RAISE EXCEPTION 'Söktexten är för lång.'; END IF; n:=greatest(1,least(coalesce(p_limit,8),8)); q:=websearch_to_tsquery('swedish',p_query); RETURN QUERY SELECT c.id,s.key,s.title,c.section,c.page,c.content,ts_rank_cd(c.tsv,q) FROM public.knowledge_chunks c JOIN public.knowledge_sources s ON s.id=c.source_id WHERE s.enabled AND (p_source_key IS NULL OR s.key=p_source_key) AND c.tsv@@q ORDER BY ts_rank_cd(c.tsv,q) DESC,c.position,c.id LIMIT n; IF FOUND THEN RETURN; END IF; q:=replace(plainto_tsquery('swedish',p_query)::text,' & ',' | ')::tsquery; RETURN QUERY SELECT c.id,s.key,s.title,c.section,c.page,c.content,ts_rank_cd(c.tsv,q) FROM public.knowledge_chunks c JOIN public.knowledge_sources s ON s.id=c.source_id WHERE s.enabled AND (p_source_key IS NULL OR s.key=p_source_key) AND c.tsv@@q ORDER BY ts_rank_cd(c.tsv,q) DESC,c.position,c.id LIMIT n; IF FOUND THEN RETURN; END IF; RETURN QUERY SELECT c.id,s.key,s.title,c.section,c.page,c.content,greatest(similarity(c.content,p_query),word_similarity(p_query,c.content)) FROM public.knowledge_chunks c JOIN public.knowledge_sources s ON s.id=c.source_id WHERE s.enabled AND (p_source_key IS NULL OR s.key=p_source_key) AND (c.content % p_query OR word_similarity(p_query,c.content)>0.3) ORDER BY greatest(similarity(c.content,p_query),word_similarity(p_query,c.content)) DESC,c.position,c.id LIMIT n; END $$;
REVOKE ALL ON FUNCTION public.search_knowledge(text,text,int) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.search_knowledge(text,text,int) TO authenticated,service_role;
CREATE FUNCTION public.knowledge_replace(p_key text,p_title text,p_audience text,p_origin text,p_chunks jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE sid uuid; BEGIN IF NOT public.auth_is_admin() THEN RAISE EXCEPTION 'Endast admin får importera kunskap.'; END IF; IF jsonb_typeof(p_chunks)<>'array' OR jsonb_array_length(p_chunks)=0 OR jsonb_array_length(p_chunks)>10000 THEN RAISE EXCEPTION 'Ogiltiga textbitar.'; END IF; INSERT INTO public.knowledge_sources(key,title,audience,origin) VALUES(p_key,p_title,p_audience,p_origin) ON CONFLICT(key) DO UPDATE SET title=excluded.title,audience=excluded.audience,origin=excluded.origin,updated_at=now() RETURNING id INTO sid; DELETE FROM public.knowledge_chunks WHERE source_id=sid; INSERT INTO public.knowledge_chunks(source_id,section,page,position,content) SELECT sid,x.section,x.page,x.position,x.content FROM jsonb_to_recordset(p_chunks) AS x(section text,page int,position int,content text); RETURN sid; END $$;
REVOKE ALL ON FUNCTION public.knowledge_replace(text,text,text,text,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.knowledge_replace(text,text,text,text,jsonb) TO authenticated;